// src/lib/bericht/anforderung.js
//
// Bericht-Baustein (Welle 2, Paket B4): Kontaktangaben und freiwillige Häkchen einer Berichtsanforderung.
// Pflicht sind NUR Vorname, Nachname (= Name) und E-Mail. Telefon ist freiwillig.
// Personendaten erscheinen nie in Fehlermeldungen oder Logs.

import { createHash } from "node:crypto";
import * as v from "@/lib/plattform/validierung";
import { PlattformFehler } from "@/lib/plattform/fehler";
import { einwilligungenAufbereiten } from "@/lib/anfrage/hinweise";

const TELEFON = /^[+0-9][0-9 ()/.-]{4,39}$/;
export const sha256 = (s) => createHash("sha256").update(String(s), "utf8").digest("hex");

/** { vorname, nachname, email, telefon } – sonst 422 mit Feldhinweis */
export function kontaktPruefen(roh) {
  const k = roh && typeof roh === "object" && !Array.isArray(roh) ? roh : {};
  const vorname = v.text(k.vorname, 80);
  const nachname = v.text(k.nachname, 80);
  const email = v.email(k.email);
  const telefonRoh = v.text(k.telefon, 40);
  if (!vorname || !nachname) throw new PlattformFehler(422, "Bitte geben Sie Vor- und Nachnamen an.", "name");
  if (!email) throw new PlattformFehler(422, "Bitte geben Sie eine gültige E-Mail-Adresse an.", "email");
  if (telefonRoh && !TELEFON.test(telefonRoh)) throw new PlattformFehler(422, "Bitte prüfen Sie die Telefonnummer – oder lassen Sie das Feld leer.", "telefon");
  return { vorname, nachname, email, telefon: telefonRoh };
}

/** Getrennte, freiwillige Häkchen (Newsletter, Werbeanruf) – nur ausdrücklich gesetzte, Werbeanruf nur mit Telefon */
export function einwilligungenPruefen(roh, { telefon, am = new Date().toISOString() } = {}) {
  return einwilligungenAufbereiten(roh, { hash: sha256, am, telefon, sprache: "de" });
}

// /api/rechner/bericht – Bericht-Baustein (Welle 2, Paket B4)
//
//   GET   → { ok, versand, modus, text }  Darf ein Bericht angefordert werden? (Oberfläche blendet das Formular sonst aus)
//   POST  { rechner, eingaben, land, kontakt: { vorname, nachname, email, telefon? }, einwilligungen?, herkunft?, website? }
//         → { ok, versand, hinweis }   Es entsteht noch KEIN Vorgang und KEIN Bericht (erst nach Double-Opt-in).
//
// Positivliste (4 Rechner), Eingabeprüfung und Neuberechnung: src/lib/bericht/neuRechnen.js – ein mitgeschicktes
// Ergebnis wird ignoriert. Rate-Limit über route() („anfrage“), Honeypot-Feld „website“, Body höchstens 8 KB.
// Personendaten stehen nie in Logs oder Fehlermeldungen dieser Route.

import { route, basisUrl } from "@/lib/plattform/server/route";
import { berichtAnfordern } from "@/lib/bericht/dienst";
import { versandStatus } from "@/lib/bericht/versand";

export const GET = route({ auth: false }, async () => ({ ok: true, ...versandStatus() }));

export const POST = route({ auth: false, limit: "anfrage", maxBytes: 8 * 1024 }, async ({ request, body }) => {
  const { rechner, eingaben, land, kontakt, einwilligungen, herkunft, website } = body; // bewusst nur diese Felder
  return berichtAnfordern({ body: { rechner, eingaben, land, kontakt, einwilligungen, herkunft, website }, basisUrl: basisUrl(request) });
});
// /api/rechner/bericht/bestaetigen – Double-Opt-in des Berichts (Welle 2, Paket B4)
//
//   POST { token } → { ok, bereits }   nur über den Knopf der Bestätigungsseite /bericht/[token] (nie per GET,
//                                       damit Mail-Scanner nicht automatisch bestätigen). 404 unbekannt, 410 abgelaufen.
//   GET  ?token=…  → { ok, zustand }    nur der Zustand, ändert nichts (410 bei Ablauf, 404 unbekannt)
//
// Erst die Bestätigung schreibt den Ketteneintrag art "doi" und legt den Vorgang an (src/lib/bericht/dienst.js).

import { route } from "@/lib/plattform/server/route";
import { PlattformFehler } from "@/lib/plattform/fehler";
import { berichtBestaetigen, berichtLesen } from "@/lib/bericht/dienst";

export const POST = route({ auth: false, limit: "anfrage", maxBytes: 1024 }, async ({ body, ip }) => {
  return berichtBestaetigen({ token: body.token, ip });
});

export const GET = route({ auth: false }, async ({ suche }) => {
  const r = await berichtLesen({ token: suche.get("token") || "" });
  if (!r.zustand) throw new PlattformFehler(404, "Dieser Link ist ungültig.", "nicht_gefunden");
  if (r.zustand === "abgelaufen") throw new PlattformFehler(410, "Dieser Link ist abgelaufen.", "abgelaufen");
  return { ok: true, zustand: r.zustand };
});
// src/lib/bericht/token.js
//
// Bericht-Baustein (Welle 2, Paket B4): Token für Double-Opt-in und Berichtslink.
//  - Zufällig, 32 Byte (base64url, 43 Zeichen). Der Klartext steht NUR im Link der E-Mail.
//  - Gespeichert wird ausschließlich der SHA-256-Hash (Hex, 64 Zeichen).
//  - Ein Token für beides: vor der Bestätigung öffnet der Link die Bestätigungsseite (Knopf → POST),
//    danach dieselbe Adresse den Bericht. So bestätigen Mail-Scanner (GET) nie automatisch.
//
// Fristen (TODO Datenschutz/Rechtsabteilung: Fristen bestätigen bzw. je Land festlegen):
//  - Bestätigung: 48 Stunden ab Anforderung, danach verfällt die Anforderung (Personendaten werden gelöscht).
//  - Berichtslink: 30 Tage ab Bestätigung, danach 410 „abgelaufen“.

import { createHash, randomBytes } from "node:crypto";

export const BESTAETIGUNG_STUNDEN = 48;
export const BERICHT_TAGE = 30;
const STUNDE = 3600 * 1000;

export const TOKEN_MUSTER = /^[A-Za-z0-9_-]{43}$/;
export const HASH_MUSTER = /^[0-9a-f]{64}$/;

/** Neues Token + Hash. Nur der Hash wird gespeichert. */
export function tokenErzeugen() {
  const token = randomBytes(32).toString("base64url");
  return { token, hash: tokenHash(token) };
}

/** SHA-256 eines formal gültigen Tokens, sonst null (kein Hash für Müll-Eingaben) */
export function tokenHash(token) {
  if (typeof token !== "string" || !TOKEN_MUSTER.test(token)) return null;
  return createHash("sha256").update(token, "utf8").digest("hex");
}

const ms = (iso) => (iso ? Date.parse(iso) : NaN);

/** Ablauf der Bestätigung ab Anforderung (ISO) */
export const bestaetigungBis = (ab = new Date()) => new Date(new Date(ab).getTime() + BESTAETIGUNG_STUNDEN * STUNDE).toISOString();
/** Ablauf des Berichtslinks ab Bestätigung (ISO) */
export const berichtBis = (ab = new Date()) => new Date(new Date(ab).getTime() + BERICHT_TAGE * 24 * STUNDE).toISOString();

/**
 * Zustand eines gespeicherten Berichts:
 *   "offen"            angefordert, Bestätigung ausstehend (und nicht abgelaufen)
 *   "in_bestaetigung"  Bestätigung läuft gerade (Sperre gegen doppelte Vorgänge)
 *   "bestaetigt"       Bericht abrufbar
 *   "abgelaufen"       Bestätigungs- oder Berichtsfrist vorbei (→ HTTP 410)
 */
export function berichtZustand(eintrag, jetzt = Date.now()) {
  if (!eintrag) return null;
  const t = typeof jetzt === "number" ? jetzt : new Date(jetzt).getTime();
  const ablauf = ms(eintrag.ablauf);
  if (!Number.isFinite(ablauf) || t > ablauf) return "abgelaufen";
  if (eintrag.bestaetigtAm) return "bestaetigt";
  if (eintrag.status === "in_bestaetigung") return "in_bestaetigung";
  return "offen";
}
// src/lib/bericht/versand.js
//
// Bericht-Baustein (Welle 2, Paket B4): Darf eine Bestätigungs-Mail rausgehen?
//
//   versandErlaubt() === true NUR, wenn
//     (a) das Demo-Backend aktiv ist – die Mail landet dann im Demo-Postausgang (db.postausgang), es geht nichts raus,
//     oder
//     (b) ausdrücklich BERICHT_TESTVERSAND=1 gesetzt ist UND NEXT_PUBLIC_SITE_ENV nicht "production" ist
//         (Frappe-Testsystem; Frappe prüft zusätzlich site_config bericht_testversand, siehe api/bericht.py).
//   In jedem anderen Fall – insbesondere immer bei NEXT_PUBLIC_SITE_ENV=production – wird nichts versendet. Die
//   Oberfläche blendet das Formular dann aus und sagt ehrlich: „Berichtsversand startet mit dem Livegang.“
//   Es werden dann auch keine Namen oder E-Mail-Adressen angenommen (keine Datenerhebung ohne Zweck).
//
// Kein Versand unter dem Namen ÖkoInvest vor dem Livegang (Inhaber-Entscheidung).
// TODO Inhaber/B0: Absendername, Absenderadresse und Versanddomain (SPF/DKIM/DMARC) festlegen – erst danach
//                  darf (b) durch einen echten Produktionsschalter ersetzt werden.

import { backendName } from "@/lib/plattform/backend";

export const VERSAND_AUS_TEXT = "Berichtsversand startet mit dem Livegang.";

/** Absender – bewusst leer bis zur Entscheidung (TODO Inhaber/B0). Nie einen echten Namen eintragen, bevor live. */
export const ABSENDER = Object.freeze({ name: null, adresse: null, domain: null, hinweis: "offen: Absender und Versanddomain legt der Inhaber fest (B0)" }); // TODO Inhaber/B0

function aktivesBackend() {
  try {
    return backendName();
  } catch {
    return null;
  }
}

/**
 * @param {{ backend?: "demo"|"frappe"|null, env?: Record<string,string|undefined> }} [o] für Tests injizierbar
 * @returns {boolean}
 */
export function versandErlaubt({ backend, env = process.env } = {}) {
  const b = backend === undefined ? aktivesBackend() : backend;
  if (String(env.NEXT_PUBLIC_SITE_ENV || "").trim().toLowerCase() === "production") return false; // nie in Produktion
  if (b === "demo") return true;
  if (b === "frappe" && env.BERICHT_TESTVERSAND === "1") return true;
  return false;
}

/** Für GET /api/rechner/bericht und die Oberfläche: { versand, modus, text } – ohne Interna */
export function versandStatus(o = {}) {
  const b = o.backend === undefined ? aktivesBackend() : o.backend;
  const versand = versandErlaubt({ ...o, backend: b });
  return {
    versand,
    modus: !versand ? "aus" : b === "demo" ? "demo" : "testversand",
    text: versand ? "" : VERSAND_AUS_TEXT,
  };
}

/** Text der Bestätigungs-Mail (ohne Ergebnis, ohne Personendaten außer der Anrede-freien Ansprache) */
export function bestaetigungsMail({ rechnerTitel, link, stunden }) {
  return {
    betreff: `Bitte bestätigen: Ihr Bericht „${rechnerTitel}“`,
    text: `Sie haben auf unserer Website einen Bericht zum ${rechnerTitel} angefordert. Bitte öffnen Sie den Link und bestätigen Sie dort Ihre E-Mail-Adresse. Erst danach erstellen wir den Bericht. Der Link ist ${stunden} Stunden gültig. Haben Sie nichts angefordert, ignorieren Sie diese E-Mail bitte – dann verfallen Ihre Angaben automatisch.`,
    link,
    linkText: "Bericht bestätigen",
  };
}

// src/lib/bericht/dienst.js
//
// Bericht-Baustein (Welle 2, Paket B4): Ablauf Anfordern → Double-Opt-in → Bericht. Nur serverseitig.
//
//  1. anfordern: Versand erlaubt? (sonst 503 „Berichtsversand startet mit dem Livegang.“ – ohne Personendaten
//     anzunehmen) → Neuberechnung (Positivliste, Eingabeprüfung) → Kontakt prüfen (Telefon freiwillig) →
//     Protokoll art "einwilligung" zweck "bericht" → Speichern (nur Token-Hash) + Bestätigungs-Mail.
//     Es entsteht KEIN Vorgang und KEIN Bericht.
//  2. bestaetigen (POST vom Knopf der Bestätigungsseite, nie per GET): Protokoll art "doi" zweck "bericht"
//     (ohne Personendaten, B3-Vertrag) → erst DANN backend.anfrageAnlegen (typ aus dem Rechner, Land,
//     strukturierte Rechnerdaten, die freiwilligen Häkchen) → Bericht 30 Tage abrufbar.
//  3. lesen: Bericht ohne Personendaten; abgelaufen → 410.
//
// Abhängigkeiten sind injizierbar (Tests); Standard: aktive Backends.

import { PlattformFehler } from "@/lib/plattform/fehler";
import { backend } from "@/lib/plattform/backend";
import { berichtBackend } from "@/lib/plattform/backend/bericht";
import { protokollAnhaengen } from "@/lib/plattform/backend/leadkette";
import { herkunftBereinigen } from "@/lib/gruppe/kanal";
import { RECHNER, neuRechnen } from "./neuRechnen";
import { annahmenbuchFuer } from "./annahmenbuch";
import { BESTAETIGUNG_STUNDEN, berichtBis, bestaetigungBis, tokenErzeugen, tokenHash } from "./token";
import { VERSAND_AUS_TEXT, bestaetigungsMail, versandErlaubt } from "./versand";
import { einwilligungenPruefen, kontaktPruefen, sha256 } from "./anforderung";
import { bundeslandFuer } from "@/lib/rechner/kommunePflichten";

/** Paket B8: Ratsvorlage → Gemeinde und Bundesland (Name wie src/lib/plattform/konstanten.js BUNDESLAENDER) */
const ratsvorlageVorgang = (ein, land) => ({
  ...(ein.gemeinde ? { gemeinde: ein.gemeinde } : {}),
  ...(bundeslandFuer(land, ein.bundesland) ? { bundesland: bundeslandFuer(land, ein.bundesland).name } : {}),
});
import { ANFORDERUNG, BERICHT_TEXT_VERSION, DOI } from "./texte";
import { berichtZaehlen } from "./zaehler";

const standard = (d = {}) => ({
  bericht: d.bericht || berichtBackend(),
  anfrage: d.anfrage || backend(),
  kette: d.kette || { protokollAnhaengen },
  versandErlaubt: d.versandErlaubt || (() => versandErlaubt()),
  jetzt: d.jetzt || (() => new Date()),
});

const objekt = (x) => (x && typeof x === "object" && !Array.isArray(x) ? x : {});
export const ANTWORT_ANGEFORDERT = `Fast geschafft: Wir haben Ihnen einen Bestätigungslink geschickt. Bitte öffnen Sie ihn innerhalb von ${BESTAETIGUNG_STUNDEN} Stunden – erst dann erstellen wir den Bericht.`;

/** POST /api/rechner/bericht */
export async function berichtAnfordern({ body, basisUrl }, deps) {
  const b = objekt(body);
  const merkmale = { rechner: b.rechner, land: typeof b.land === "string" ? b.land.toUpperCase() : "" };
  if (b.website) {
    berichtZaehlen({ ...merkmale, ereignis: "abgelehnt" });
    return { ok: true, versand: true, hinweis: ANTWORT_ANGEFORDERT }; // Honeypot: still verwerfen
  }
  const d = standard(deps);
  if (!d.versandErlaubt()) {
    berichtZaehlen({ ...merkmale, ereignis: "abgelehnt" });
    throw new PlattformFehler(503, VERSAND_AUS_TEXT, "versand_aus");
  }
  try {
    // Die Route übergibt body.ergebnis o. Ä. nie weiter – gerechnet wird ausschließlich hier.
    const r = neuRechnen({ rechner: b.rechner, eingaben: b.eingaben, land: b.land });
    const kontakt = kontaktPruefen(b.kontakt);
    const am = d.jetzt();
    const einwilligungen = einwilligungenPruefen(b.einwilligungen, { telefon: kontakt.telefon, am: am.toISOString() });
    const { kanal } = herkunftBereinigen(objekt(b.herkunft));
    const annahmen = annahmenbuchFuer(r.rechner, r.eingaben);
    const { token, hash } = tokenErzeugen();
    const link = `${String(basisUrl || "").replace(/\/$/, "")}/bericht/${token}`;

    await d.kette.protokollAnhaengen({
      email: kontakt.email,
      art: "einwilligung",
      zweck: "bericht",
      textId: ANFORDERUNG.textId,
      textVersion: BERICHT_TEXT_VERSION,
      textHash: sha256(ANFORDERUNG.text),
      kanal: "web_formular",
      land: r.land,
      zeit: am.toISOString(),
    });
    await d.bericht.berichtAnlegen({
      tokenHash: hash,
      rechner: r.rechner,
      land: r.land,
      eingaben: r.eingaben,
      ergebnis: { titel: r.titel, ...r.ergebnis, annahmen },
      pruefId: r.pruefId,
      stand: r.stand,
      ablauf: bestaetigungBis(am),
      kontakt,
      einwilligungen,
      kanal,
      mail: bestaetigungsMail({ rechnerTitel: r.titel, link, stunden: BESTAETIGUNG_STUNDEN }),
    });
    berichtZaehlen({ rechner: r.rechner, land: r.land, ereignis: "angefordert" });
    return { ok: true, versand: true, hinweis: ANTWORT_ANGEFORDERT };
  } catch (e) {
    berichtZaehlen({ ...merkmale, ereignis: "abgelehnt" });
    throw e;
  }
}

/** Strukturierte Rechnerdaten für den Vorgang (keine Personendaten) */
export function vorgangDaten(e) {
  const ein = objekt(e.eingaben);
  return {
    quelle: `bericht_${e.rechner}`,
    land: e.land,
    ...(Number.isFinite(ein.ha) ? { ha: ein.ha } : {}),
    ...(ein.regionId ? { regionId: ein.regionId } : {}),
    ...(e.rechner === "flaechencheck" && ein.nutzung ? { nutzung: ein.nutzung } : {}),
    // Paket B8: Gemeinde und Bundesland (Name) oben, damit Kommunen-Positivliste und Routing je Gebiet sie lesen
    ...(e.rechner === "ratsvorlage" ? ratsvorlageVorgang(ein, e.land) : {}),
    bericht: {
      rechner: e.rechner,
      pruefId: e.pruefId,
      stand: e.stand,
      kennzahlen: (e.ergebnis?.kennzahlen || []).slice(0, 12).map((k) => `${k.label}: ${k.wert}${k.zusatz ? ` (${k.zusatz})` : ""}`),
    },
    eingaben: ein,
  };
}

/** POST /api/rechner/bericht/bestaetigen { token } */
export async function berichtBestaetigen({ token, ip = "" }, deps) {
  const hash = tokenHash(token);
  if (!hash) throw new PlattformFehler(404, "Dieser Link ist ungültig.", "nicht_gefunden");
  const d = standard(deps);
  const start = await d.bericht.berichtBestaetigungBeginnen({ tokenHash: hash, jetztMs: d.jetzt().getTime() });
  if (!start || start.zustand === null) throw new PlattformFehler(404, "Dieser Link ist ungültig.", "nicht_gefunden");
  if (start.zustand === "abgelaufen") throw new PlattformFehler(410, "Dieser Link ist abgelaufen. Bitte fordern Sie den Bericht im Rechner neu an.", "abgelaufen");
  if (start.zustand === "bestaetigt") return { ok: true, bereits: true };
  if (start.zustand === "in_bestaetigung") throw new PlattformFehler(409, "Die Bestätigung läuft bereits – bitte laden Sie die Seite in einem Moment neu.", "konflikt");
  const e = start.eintrag;
  try {
    await d.kette.protokollAnhaengen({
      email: e.kontakt.email,
      art: "doi",
      zweck: "bericht",
      textId: DOI.textId,
      textVersion: BERICHT_TEXT_VERSION,
      textHash: sha256(DOI.text),
      kanal: "doi_link",
      land: e.land,
    });
    const anfrage = await d.anfrage.anfrageAnlegen({
      typ: RECHNER[e.rechner].vorgangTyp,
      kontakt: { ...e.kontakt, land: e.land },
      daten: vorgangDaten(e),
      herkunft: { kanal: e.kanal || "Direkt" },
      ip,
      einwilligungText: ANFORDERUNG.hinweis,
      hinweis: { id: "hinweis_bericht", version: BERICHT_TEXT_VERSION, rechtsgrundlage: "Art. 6 Abs. 1 lit. b DSGVO", textHash: sha256(ANFORDERUNG.hinweis) },
      einwilligungen: Array.isArray(e.einwilligungen) ? e.einwilligungen : [],
      nutzer: null,
    });
    await d.bericht.berichtBestaetigungAbschliessen({ tokenHash: hash, vorgangId: anfrage.id, ablauf: berichtBis(d.jetzt()), jetztMs: d.jetzt().getTime() });
    berichtZaehlen({ rechner: e.rechner, land: e.land, ereignis: "bestaetigt" });
    return { ok: true, bereits: false };
  } catch (err) {
    await d.bericht.berichtBestaetigungZuruecksetzen({ tokenHash: hash }).catch(() => {});
    berichtZaehlen({ rechner: e.rechner, land: e.land, ereignis: "abgelehnt" });
    throw err;
  }
}

/** Für die Seite /bericht/[token] und GET der Bestätigungs-API: { zustand, bericht? } – nie Personendaten */
export async function berichtLesen({ token }, deps) {
  const hash = tokenHash(token);
  if (!hash) return { zustand: null };
  const d = { bericht: deps?.bericht || berichtBackend(), jetzt: deps?.jetzt || (() => new Date()) };
  return d.bericht.berichtLesen({ tokenHash: hash, jetztMs: d.jetzt().getTime() });
}
// src/lib/anfrage/hinweise.js
//
// Datenschutz-Hinweis und optionale Einwilligungen im Anfrageformular (Paket C, Welle 1).
//
// ┌─────────────────────────────────────────────────────────────────────────────────────────────┐
// │ ENTWURF – KEINE FREIGABE. Alle Texte in dieser Datei sind Platzhalter des Agenten-Teams.      │
// │ Den finalen Wortlaut liefert Strang R (Rechtstexte, Anwalt). Bis dahin: Seite nicht öffentlich │
// │ bzw. noindex. Jede Textänderung → VERSION erhöhen (der Hash wird je Eintrag gespeichert).      │
// └─────────────────────────────────────────────────────────────────────────────────────────────┘
//
// Rechtliche Linie laut Masterplan Abschnitt 5 (zu prüfen durch Strang R):
//  - Die Bearbeitung der Anfrage stützt sich auf Art. 6 Abs. 1 lit. b DSGVO (vorvertragliche Maßnahme auf
//    Anfrage) – dafür wird KEINE Einwilligung verlangt, sondern informiert (Hinweis, kein Pflicht-Häkchen).
//  - Ein ausdrücklich gewählter Rückruf ist Teil der Anfrage (lit. b); die Nummer wird nur dafür genutzt.
//  - Werbeanrufe und Werbe-Mails nur mit eigener, nicht vorbelegter Einwilligung
//    (DE § 7 UWG; AT § 174 TKG 2021, auch B2B; CH Art. 3 Abs. 1 lit. o UWG) – drei getrennte Häkchen.
//  - Die Weitergabe an Partner setzt benannte Partner voraus; solange keine benannt sind, bleibt das
//    Häkchen ausgeblendet (aktiv: false).

// 2026-10-08: englischer Verweis ohne „(in German)“ – die Datenschutzerklärung gibt es jetzt als englische
// Übersetzung zur Information (/en/datenschutz; maßgeblich bleibt die deutsche Fassung).
export const HINWEIS_VERSION = "ENTWURF-2026-10-08";

/** Hinweis statt Pflicht-Einwilligung (der vollständige Text wird mit Version und Hash beim Vorgang gespeichert) */
const HINWEIS_KERN = "Wir verarbeiten Ihre Angaben, um Ihre Anfrage zu beantworten. Eine Einwilligung ist dafür nicht nötig.";
const HINWEIS_VERWEIS_VOR = "Einzelheiten und Ihre Rechte finden Sie in der";
const HINWEIS_VERWEIS_LINK = "Datenschutzerklärung";
export const HINWEIS = Object.freeze({
  id: "hinweis_anfrage",
  rechtsgrundlage: "Art. 6 Abs. 1 lit. b DSGVO",
  version: HINWEIS_VERSION,
  kern: HINWEIS_KERN,
  verweisVor: HINWEIS_VERWEIS_VOR,
  verweisLink: HINWEIS_VERWEIS_LINK, // Link auf /datenschutz
  text: `${HINWEIS_KERN} ${HINWEIS_VERWEIS_VOR} ${HINWEIS_VERWEIS_LINK}.`,
  // Englische Seiten (/en): eigener Wortlaut, eigener Hash
  en: Object.freeze({
    kern: "We process your details to answer your enquiry. No consent is needed for this.",
    verweisVor: "Details and your rights are set out in our",
    verweisLink: "privacy policy",
    text: "We process your details to answer your enquiry. No consent is needed for this. Details and your rights are set out in our privacy policy.",
  }),
});

/** Rückruf-Wunsch (Teil der Anfrage, keine Werbeeinwilligung) */
export const RUECKRUF = Object.freeze({
  id: "rueckruf",
  version: HINWEIS_VERSION,
  text: "Bitte rufen Sie mich zu dieser Anfrage zurück.",
  zusatz: "Dann brauchen wir Ihre Telefonnummer. Wir nutzen sie nur für diese Anfrage.",
  en: Object.freeze({ text: "Please call me back about this enquiry.", zusatz: "We then need your phone number. We use it only for this enquiry." }),
});

/**
 * Optionale, getrennte Einwilligungen – nie vorbelegt, nie Voraussetzung für die Anfrage.
 *  nurMitTelefon: nur anzeigen, wenn das Formular ein Telefonfeld hat
 *  aktiv: false → nicht anzeigen und serverseitig nicht annehmen
 */
export const EINWILLIGUNGEN = Object.freeze([
  Object.freeze({
    id: "werbeanruf",
    zweck: "werbeanruf", // Einwilligungsprotokoll (src/lib/anfrage/protokoll.js)
    version: HINWEIS_VERSION,
    nurMitTelefon: true,
    aktiv: true,
    text: "Ja, ÖkoInvest darf mich auch später telefonisch zu passenden eigenen Angeboten ansprechen. Ich kann das jederzeit widerrufen.",
    textEn: "Yes, ÖkoInvest may also call me later about suitable offers of its own. I can withdraw this at any time.",
  }),
  Object.freeze({
    id: "newsletter",
    zweck: "newsletter", // gilt erst nach Double-Opt-in (Eintrag art "doi", Paket B4)
    version: HINWEIS_VERSION,
    nurMitTelefon: false,
    aktiv: true,
    // TODO Strang R + Betrieb: Double-Opt-in-Strecke fehlt noch – bis dahin wird nur der Wunsch gespeichert (doi: "ausstehend"), es geht nichts raus.
    text: "Ja, ich möchte Fachinformationen und Fristen-Hinweise für mein Land per E-Mail erhalten. Die Anmeldung bestätige ich per E-Mail; Abmeldung jederzeit.",
    textEn: "Yes, I would like to receive market information and deadline alerts for my country by e-mail. I will confirm by e-mail; unsubscribe at any time.",
  }),
  Object.freeze({
    id: "partner",
    zweck: "weitergabe_partner",
    version: HINWEIS_VERSION,
    nurMitTelefon: false,
    aktiv: false, // TODO Strang R: Partner namentlich benennen, erst dann einschalten
    text: "Ja, meine Anfrage darf an folgende Partner weitergegeben werden: [Partnerliste folgt – Strang R].",
    textEn: "Yes, my enquiry may be passed on to the following partners: [partner list to follow].",
  }),
]);

export const EINWILLIGUNG_IDS = Object.freeze(EINWILLIGUNGEN.filter((e) => e.aktiv).map((e) => e.id));

/**
 * Welle 2, Paket B3: Häkchen-ID → Zweck im Einwilligungsprotokoll (werbeanruf | newsletter | weitergabe_partner).
 * Es gibt KEINE mutmaßliche Einwilligung (auch nicht B2B): Nur ein ausdrücklich gesetztes Häkchen erzeugt einen Eintrag.
 */
export const zweckFuer = (id) => EINWILLIGUNGEN.find((e) => e.id === id)?.zweck || "";

/** Wortlaut je Sprache (Standard Deutsch) */
export const einwilligungText = (e, sprache) => (sprache === "en" && e.textEn ? e.textEn : e.text);
export const hinweisText = (sprache) => (sprache === "en" ? HINWEIS.en.text : HINWEIS.text);

/** Für das Formular: welche Häkchen werden angezeigt? */
export function einwilligungenFuer({ mitTelefon }) {
  return EINWILLIGUNGEN.filter((e) => e.aktiv && (!e.nurMitTelefon || mitTelefon));
}

/**
 * Eingabe des Formulars → Protokoll-Einträge (nur erteilte, nur bekannte, nur aktive).
 * hash: Funktion text → Hex-Hash (Server: SHA-256); am: Zeitstempel (ISO).
 * Telefon-Einwilligung ohne Telefonnummer wird verworfen. sprache: "en" → Hash über den englischen Wortlaut.
 */
export function einwilligungenAufbereiten(eingabe, { hash, am, telefon, sprache }) {
  const roh = eingabe && typeof eingabe === "object" && !Array.isArray(eingabe) ? eingabe : {};
  const out = [];
  for (const e of EINWILLIGUNGEN) {
    if (!e.aktiv || roh[e.id] !== true) continue;
    if (e.nurMitTelefon && !telefon) continue;
    out.push({ id: e.id, erteilt: true, am, version: e.version, sprache: sprache === "en" ? "en" : "de", textHash: hash(einwilligungText(e, sprache)), ...(e.id === "newsletter" ? { doi: "ausstehend" } : {}) });
  }
  return out;
}

