// /api/newsletter – Newsletter je Land (Welle 3, Paket NL)
//
//   GET   → { ok, aktiv, modus }   Nimmt der Newsletter Anmeldungen an? (Baustein blendet das Formular sonst aus)
//   POST  { email, land, themen[], sprache?, quelle?, herkunft?, website? } → { ok, hinweis }
//         Es entsteht nur eine OFFENE Anmeldung (Double-Opt-in, src/lib/newsletter/dienst.js). Antwort immer gleich.
//
// Rate-Limit über route() („anfrage“), Honeypot „website“, Body höchstens 4 KB. Personendaten nie in Logs/Fehlern.

import { route, basisUrl } from "@/lib/plattform/server/route";
import { anmelden } from "@/lib/newsletter/dienst";
import { newsletterStatus } from "@/lib/newsletter/versand";

export const GET = route({ auth: false }, async () => ({ ok: true, ...newsletterStatus() }));

export const POST = route({ auth: false, limit: "anfrage", maxBytes: 4 * 1024 }, async ({ request, body }) => {
  const { email, land, themen, sprache, quelle, herkunft, website } = body; // bewusst nur diese Felder
  return anmelden({ body: { email, land, themen, sprache, quelle, herkunft, website }, basisUrl: basisUrl(request) });
});
EOF
cat > src/app/api/newsletter/bestaetigen/route.js <<'EOF'
// /api/newsletter/bestaetigen – Double-Opt-in des Newsletters (Welle 3, Paket NL)
//
//   POST { token } → { ok, bereits }   nur über den Knopf der Seite /newsletter/abo/[token] (nie per GET, damit
//                                       Mail-Scanner nicht automatisch bestätigen). 404 unbekannt, 410 abgelaufen.

import { route, basisUrl } from "@/lib/plattform/server/route";
import { bestaetigen } from "@/lib/newsletter/dienst";

export const POST = route({ auth: false, limit: "anfrage", maxBytes: 1024 }, async ({ request, body }) => {
  return bestaetigen({ token: body.token, basisUrl: basisUrl(request) });
});
EOF
cat > src/app/api/newsletter/abmelden/route.js <<'EOF'
// /api/newsletter/abmelden – Abmeldung mit einem Klick (Welle 3, Paket NL)
//
//   POST { token }                              Knopf der Seite /newsletter/abo/[token] (JSON, mit Origin-Prüfung)
//   POST ?token=…  Body „List-Unsubscribe=One-Click“  Ein-Klick-Abmeldung aus dem Mailprogramm nach RFC 8058
//        (Kopfzeilen List-Unsubscribe / List-Unsubscribe-Post jeder Mail). Mailprogramme senden keinen Origin –
//        das Token genügt: Wer es kennt, kann nur abmelden, nie anmelden oder lesen. Antwort ohne Inhalt.
//   GET  ändert NIE etwas (Link-Scanner) – leitet auf die Seite mit dem Abmeldeknopf.

import { NextResponse } from "next/server";
import { route, fehlerAntwort } from "@/lib/plattform/server/route";
import { grenze, rateLimit } from "@/lib/plattform/server/rateLimit";
import { ipAdresse } from "@/lib/ipAdresse";
import { abmelden } from "@/lib/newsletter/dienst";
import { TOKEN_MUSTER } from "@/lib/bericht/token";

const perKnopf = route({ auth: false, limit: "anfrage", maxBytes: 1024 }, async ({ body }) => abmelden({ token: body.token }));

async function einKlick(request) {
  try {
    rateLimit(`anfrage:${ipAdresse(request) || "ohne-ip"}`, ...grenze("anfrage"));
    const text = (await request.text()).slice(0, 200);
    if (!/(^|&)List-Unsubscribe=One-Click(&|$)/.test(text)) return NextResponse.json({ ok: false }, { status: 400, headers: { "Cache-Control": "no-store" } });
    await abmelden({ token: request.nextUrl.searchParams.get("token") || "" });
    return new NextResponse(null, { status: 200, headers: { "Cache-Control": "no-store" } });
  } catch (e) {
    return fehlerAntwort(e);
  }
}

export async function POST(request, ctx) {
  const typ = (request.headers.get("content-type") || "").toLowerCase();
  if (request.nextUrl.searchParams.has("token") && (typ.startsWith("application/x-www-form-urlencoded") || typ.startsWith("multipart/form-data"))) return einKlick(request);
  return perKnopf(request, ctx);
}

export async function GET(request) {
  const token = request.nextUrl.searchParams.get("token") || "";
  const ziel = new URL(TOKEN_MUSTER.test(token) ? `/newsletter/abo/${token}` : "/newsletter", request.url);
  const res = NextResponse.redirect(ziel, 303);
  res.headers.set("Referrer-Policy", "no-referrer");
  res.headers.set("Cache-Control", "no-store");
  return res;
}
EOF

