  if (zeile) {
    return (
      <p className={cn("flex items-start gap-2 text-[13.5px] leading-relaxed text-ink-600", className)} data-land-hinweis={l}>
        <Clock aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-navy-500" />
        <span>
          {satz}{" "}

